// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// EmpiarControllerCreateMetadataJSON Add file, pixel spacing, contour level and description to deposition in OneDep
	// (POST /empiar/metadata)
	EmpiarControllerCreateMetadataJSON(ctx context.Context, request EmpiarControllerCreateMetadataJSONRequestObject) (EmpiarControllerCreateMetadataJSONResponseObject, error)
	// EmpiarControllerGetSchema Retrieve the current schema for EMPIAR depositions
	// (GET /empiar/schema)
	EmpiarControllerGetSchema(ctx context.Context, request EmpiarControllerGetSchemaRequestObject) (EmpiarControllerGetSchemaResponseObject, error)
	// OneDepControllerCreateNewDeposition Create a new deposition to OneDep
	// (POST /onedep)
	OneDepControllerCreateNewDeposition(ctx context.Context, request OneDepControllerCreateNewDepositionRequestObject) (OneDepControllerCreateNewDepositionResponseObject, error)
	// OneDepControllerDownloadMetadata Get a cif file with metadata for manual deposition in OneDep
	// (POST /onedep/metadata)
	OneDepControllerDownloadMetadata(ctx context.Context, request OneDepControllerDownloadMetadataRequestObject) (OneDepControllerDownloadMetadataResponseObject, error)
	// OneDepControllerDownloadCif Get a cif file with metadata and coordinates for manual deposition in OneDep
	// (POST /onedep/pdb)
	OneDepControllerDownloadCif(ctx context.Context, request OneDepControllerDownloadCifRequestObject) (OneDepControllerDownloadCifResponseObject, error)
	// OneDepControllerUploadFile Add file, pixel spacing, contour level and description to deposition in OneDep
	// (POST /onedep/{depID}/file)
	OneDepControllerUploadFile(ctx context.Context, request OneDepControllerUploadFileRequestObject) (OneDepControllerUploadFileResponseObject, error)
	// OneDepControllerUploadMetadata Add a cif file with metadata to deposition in OneDep
	// (POST /onedep/{depID}/metadata)
	OneDepControllerUploadMetadata(ctx context.Context, request OneDepControllerUploadMetadataRequestObject) (OneDepControllerUploadMetadataResponseObject, error)
	// OneDepControllerUploadPdb Add coordinates and description to deposition in OneDep
	// (POST /onedep/{depID}/pdb)
	OneDepControllerUploadPdb(ctx context.Context, request OneDepControllerUploadPdbRequestObject) (OneDepControllerUploadPdbResponseObject, error)
	// OneDepControllerProcess Process deposition to OneDep
	// (POST /onedep/{depID}/process)
	OneDepControllerProcess(ctx context.Context, request OneDepControllerProcessRequestObject) (OneDepControllerProcessResponseObject, error)
	// OtherControllerGetVersion Return current version
	// (GET /version)
	OtherControllerGetVersion(ctx context.Context, request OtherControllerGetVersionRequestObject) (OtherControllerGetVersionResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

